package mcpserver

import (
	"fmt"
	"github.com/aristath/songya"
	"strings"
)

// WriteSchemas is generated by Songya, including the selected user's exact IDs
// and plain-language definitions. Clients must not maintain their own taxonomy.
func WriteSchemas(cfg songya.TypeConfiguration) map[string]map[string]any {
	story := schema(map[string]any{"id": str("Existing story ID; omit to create"), "user": str("Owner of a new story; omit on update to keep ownership"), "title": str("Story title"), "text": str("All story words; replaces the old words"), "append": str("Words to add"), "metadata": object(), "relations": relationsSchema()})
	result := map[string]map[string]any{"save_memory": memorySchema(), "save_entity": namedSchema(true), "save_topic": namedSchema(false), "save_story": story}
	for name, kind := range map[string]songya.Destination{"save_memory": songya.Memories, "save_entity": songya.Entities, "save_topic": songya.Topics, "save_story": songya.Stories} {
		properties := result[name]["properties"].(map[string]any)
		properties["type_user"] = str("Selected user for classification. This does not change record ownership. The app supplies it")
		typeField := str("Type ID from the selected user's configured choices. Omit to keep the classification; an empty string clears only this user's classification. Do not invent a type")
		if cfg.User != "" {
			properties["type_user"] = map[string]any{"type": "string", "enum": []string{cfg.User}, "description": "Selected classification user. The app supplies this value"}
			choices := []string{""}
			var definitions strings.Builder
			fmt.Fprintf(&definitions, "Type choices for %s, user %q. Omit type if none fits; empty string clears this user's assignment.\n", kind, cfg.User)
			for _, def := range cfg.Kinds[kind] {
				choices = append(choices, def.ID)
				fmt.Fprintf(&definitions, "%s: %s\n", def.ID, def.Description)
			}
			if len(choices) == 1 {
				definitions.WriteString("No types configured. Omit type.")
			}
			typeField["enum"] = choices
			typeField["description"] = definitions.String()
		}
		properties["type"] = typeField
		// Inline identities use the same configured types; a topic may have no types.
		if rel, ok := properties["relations"].(map[string]any); ok {
			item := rel["items"].(map[string]any)
			target := item["properties"].(map[string]any)["target"].(map[string]any)
			variants := target["anyOf"].([]any)
			inline := variants[1].(map[string]any)
			inline["properties"].(map[string]any)["type"] = str("Optional type ID for this inline entity or topic from the selected user's configuration. Omit when no configured type fits")
		}
	}
	return result
}
